module benchmark/solution

import std/fs (writeFile)

pure func computeSum(a: int, b: int) -> int = a + b

func printSum(a: int, b: int) -> () ! {IO} {
  let sum = computeSum(a, b);
  println("Sum: ${show(sum)}")
}

func logToFile(filename: string, message: string) -> () ! {IO, FS} =
  writeFile(filename, message)

export func main() -> () ! {IO, FS} {
  let result = computeSum(10, 20);
  printSum(10, 20);
  logToFile("output.txt", "Sum was ${show(result)}");
  println("Done")
}
